.radio-option__input:focus-visible ~ .radio-option__control {
  outline: 2.5px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* Label text */
.radio-option__label-text {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

.radio-option__name {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text-primary);
}

.radio-option__desc {
  font-size: 0.8rem;
  color: var(--color-text-secondary);
}

/* Icon */
.radio-option__icon {
  margin-left: auto;
  font-size: 1.125rem;
  opacity: 0.6;
  flex-shrink: 0;
}

.radio-option:has(.radio-option__input:checked) .radio-option__icon {
  opacity: 1;
