 * Notification Preferences — React-style component structure
 * rendered as vanilla JS into #root (no build step required).
 */

// ── Helpers ─────────────────────────────────────────────────────────────────

function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  Object.entries(attrs).forEach(([key, val]) => {
    if (key === "className") {
      node.className = val;
    } else if (key === "htmlFor") {
      node.htmlFor = val;
    } else if (key.startsWith("on") && typeof val === "function") {
      node.addEventListener(key.slice(2).toLowerCase(), val);
    } else if (key === "dataset") {
      Object.entries(val).forEach(([dk, dv]) => (node.dataset[dk] = dv));
    } else {
      node.setAttribute(key, val);
    }
  });
  children.flat(Infinity).forEach((child) => {
    if (child == null) return;
    node.append(typeof child === "string" ? document.createTextNode(child) : child);
  });
  return node;
}

// ── Data ─────────────────────────────────────────────────────────────────────

const NOTIFICATION_OPTIONS = [
  {
    id: "opt-email",
    value: "email",
    name: "Email",
    description: "Receive updates in your inbox",
    icon: "✉️",
  },
  {
    id: "opt-sms",
    value: "sms",
    name: "SMS",
    description: "Get text messages on your phone",
    icon: "💬",
  },
  {
    id: "opt-push",
    value: "push",
    name: "Push Notifications",
    description: "Instant alerts on your device",
    icon: "🔔",
  },
];

// ── Components ────────────────────────────────────────────────────────────────

function RadioOption({ id, value, name, description, icon, groupName }) {
  const inputId = id;
  const labelId = `${id}-label`;

  const input = el("input", {
    className: "radio-option__input",
    type: "radio",
    id: inputId,
    name: groupName,
    value,
    "aria-describedby": `${id}-desc`,
  });

  const control = el("span", {
    className: "radio-option__control",
    "aria-hidden": "true",
  });

  const labelText = el(
    "span",
    { className: "radio-option__label-text" },
    el("span", { className: "radio-option__name", id: labelId }, name),
    el(
      "span",
      { className: "radio-option__desc", id: `${id}-desc` },
      description
    )
  );

  const iconEl = el(
    "span",
    { className: "radio-option__icon", "aria-hidden": "true" },
    icon
  );

  const label = el(
    "label",
    { className: "radio-option", htmlFor: inputId },
    input,
    control,
    labelText,
    iconEl
  );

  return label;
}

function RadioGroup({ legendText, hint, options, name, errorId }) {
  const legend = el("legend", { className: "form-field__legend" }, legendText);

  const hintEl = el(
    "p",
    { className: "form-field__hint", id: `${name}-hint` },
    hint
  );

  const radioEls = options.map((opt) =>
    RadioOption({ ...opt, groupName: name })
  );

  const fieldset = el(
    "fieldset",
    {
      className: "radio-group",
      "aria-describedby": `${name}-hint ${errorId}`,
    },
    legend,
    hintEl,
    ...radioEls
  );

  return fieldset;
}

function SuccessBanner() {
  const icon = el("span", { "aria-hidden": "true" }, "✓");
  const banner = el(
    "div",
    {
      className: "success-banner",
      role: "status",
      "aria-live": "polite",
      id: "success-banner",
    },
    icon,
    "Your preference has been saved!"
  );
  return banner;
}

function PreferencesForm() {
  const errorId = "notif-error";

  const errorMsg = el(
    "p",
    {
      className: "field-error",
      id: errorId,
      "aria-live": "polite",
      role: "alert",
    },
    "Please select a notification preference to continue."
  );

  const radioGroup = RadioGroup({
    legendText: "How do you prefer to receive notifications?",
    hint: "Choose one option",
    options: NOTIFICATION_OPTIONS,
    name: "notification-preference",
    errorId,
  });

  const formField = el(
    "div",
    { className: "form-field" },
    radioGroup,
    errorMsg
  );

  const successBanner = SuccessBanner();

  const submitBtn = el(
    "button",
    { className: "btn-submit", type: "submit" },
    "Save Preference"
  );

  const form = el(
    "form",
    {
      className: "preferences-form",
      novalidate: "",
      id: "preferences-form",
    },
    formField,
    successBanner,
    submitBtn
  );

  // ── Event handling ──
  form.addEventListener("submit", (e) => {
    e.preventDefault();

    const selected = form.querySelector(
      'input[name="notification-preference"]:checked'
    );

    if (!selected) {
      // Show validation error
      errorMsg.style.display = "block";
      errorMsg.setAttribute("aria-live", "assertive");
      // Focus first radio for correction
      const firstRadio = form.querySelector(
        'input[name="notification-preference"]'
      );
      firstRadio?.focus();
      successBanner.classList.remove("is-visible");
      return;
    }

    // Clear error, show success
    errorMsg.style.display = "none";
    successBanner.classList.add("is-visible");
    successBanner.focus();
  });

  // Clear error once user makes a selection
  form.addEventListener("change", (e) => {
    if (e.target.name === "notification-preference") {
      errorMsg.style.display = "none";
    }
  });

  return form;
}

function App() {
  const header = el(
    "header",
    { className: "card__header" },
    el("h1", { className: "card__title" }, "Notification Preferences"),
    el(
      "p",
      { className: "card__subtitle" },
      "Choose how you'd like to stay informed."
    )
  );

  const card = el(
    "div",
    { className: "card" },
    header,
    PreferencesForm()
  );

  return card;
}

// ── Mount ─────────────────────────────────────────────────────────────────────

const root = document.getElementById("root");
if (root) {
  // Skip link
  const skipLink = el(
    "a",
    { className: "skip-link", href: "#main-content" },
    "Skip to main content"
  );
  document.body.prepend(skipLink);

  root.appendChild(App());
}
