const NOTIFICATION_OPTIONS = [
  {
    id: "opt-email",
    value: "email",
    name: "Email",
    description: "Receive updates in your inbox",
    icon: "✉️",
  },
  {
    id: "opt-sms",
    value: "sms",
    name: "SMS",
    description: "Get text messages on your phone",
    icon: "💬",
  },
  {
    id: "opt-push",
    value: "push",
    name: "Push Notifications",
    description: "Instant alerts on your device",
    icon: "🔔",
  },
];

// ── Components ────────────────────────────────────────────────────────────────

function RadioOption({ id, value, name, description, icon, groupName }) {
  const inputId = id;
  const labelId = `${id}-label`;

  const input = el("input", {
    className: "radio-option__input",
    type: "radio",
    id: inputId,
    name: groupName,
    value,
    "aria-describedby": `${id}-desc`,
