  const control = el("span", {
    className: "radio-option__control",
    "aria-hidden": "true",
  });

  const labelText = el(
    "span",
    { className: "radio-option__label-text" },
    el("span", { className: "radio-option__name", id: labelId }, name),
    el(
      "span",
      { className: "radio-option__desc", id: `${id}-desc` },
      description
    )
  );

  const iconEl = el(
    "span",
    { className: "radio-option__icon", "aria-hidden": "true" },
    icon
  );

