    control,
    labelText,
    iconEl
  );

  return label;
}

function RadioGroup({ legendText, hint, options, name, errorId }) {
  const legend = el("legend", { className: "form-field__legend" }, legendText);

  const hintEl = el(
    "p",
    { className: "form-field__hint", id: `${name}-hint` },
    hint
  );

  const radioEls = options.map((opt) =>
    RadioOption({ ...opt, groupName: name })
  );

